class Solution {
public:
    vector<bool> prefixesDivBy5(vector<int>& nums) {
        int cur = 0;
        vector<bool> res;
        res.reserve(nums.size());
        for (int bit : nums) {
            cur = (cur * 2 + bit) % 5;
            res.push_back(cur == 0);
        }
        return res;
    }
};

class Solution {
    public List<Boolean> prefixesDivBy5(int[] nums) {
        int cur = 0;
        List<Boolean> res = new ArrayList<>(nums.length);
        for (int bit : nums) {
            cur = (cur * 2 + bit) % 5;
            res.add(cur == 0);
        }
        return res;
    }
}

var prefixesDivBy5 = function(nums) {
    let cur = 0;
    const res = [];
    for (const bit of nums) {
        cur = (cur * 2 + bit) % 5;
        res.push(cur === 0);
    }
    return res;
};
